import { chromium } from 'playwright';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  page.on('console', msg => console.log(`[BROWSER CONSOLE] ${msg.type()}: ${msg.text()}`));
  page.on('pageerror', err => console.error(`[BROWSER ERROR]`, err));
  page.on('requestfailed', req => console.warn(`[REQUEST FAILED] ${req.url()} - ${req.failure()?.errorText}`));

  console.log('Navigating to https://libriq.app ...');
  await page.goto('https://libriq.app', { waitUntil: 'networkidle' });

  const state = await page.evaluate(() => {
    return {
      LibriqConfig: window.LibriqConfig,
      firebaseState: window.LibriqFirebase?.getState?.() || null,
      title: document.title,
      fallbackVisible: !document.getElementById('sessionFallbackModal')?.hidden,
      fallbackTitle: document.getElementById('sessionFallbackTitle')?.textContent,
      fallbackCopy: document.getElementById('sessionFallbackCopy')?.textContent,
    };
  });

  console.log('PAGE EVALUATE STATE:', JSON.stringify(state, null, 2));

  await browser.close();
})();

