import fs from 'node:fs';

const filePath = 'frontend/index.html';
const content = fs.readFileSync(filePath, 'utf8');

const target = `          <label class="search-filter-field">
            <span>Source</span>
            <select id="searchFilterSource" class="form-select search-filter-select">
              <option value="all">All sources</option>
              <option value="openlibrary">Open Library</option>
              <option value="google">Google Books</option>
            </select>
          </label>`.replace(/\n/g, '\r\n');

const replacement = `          <div class="search-filter-field custom-select-field">
            <span id="searchFilterSourceLabel">Source</span>
            <div class="custom-select-wrapper" id="searchFilterSourceWrapper">
              <button type="button" class="form-select custom-select-trigger" id="searchFilterSourceTrigger" aria-haspopup="listbox" aria-expanded="false" aria-labelledby="searchFilterSourceLabel searchFilterSourceTrigger">
                <span class="custom-select-value" id="searchFilterSourceValue">All sources</span>
                <i class="ph ph-caret-down" aria-hidden="true"></i>
              </button>
              <ul class="custom-select-listbox" id="searchFilterSourceListbox" role="listbox" tabindex="-1" hidden>
                <li class="custom-select-option is-selected" role="option" data-value="all" aria-selected="true">All sources</li>
                <li class="custom-select-option" role="option" data-value="openlibrary" aria-selected="false">Open Library</li>
                <li class="custom-select-option" role="option" data-value="google" aria-selected="false">Google Books</li>
              </ul>
              <input type="hidden" id="searchFilterSource" name="source" value="all" />
            </div>
          </div>`.replace(/\n/g, '\r\n');

if (content.includes(target)) {
  fs.writeFileSync(filePath, content.replace(target, replacement), 'utf8');
  console.log('Replaced select in frontend/index.html successfully');
} else {
  console.error('Target not found in frontend/index.html');
  process.exit(1);
}

