import fs from 'node:fs';

const searchPath = 'frontend/js/search.js';
let searchContent = fs.readFileSync(searchPath, 'utf8');

const syncNeedle = '    if (els.filterSource) els.filterSource.value = activeFilters.source;';
const syncReplacement = `    if (els.filterSource) {
      els.filterSource.value = activeFilters.source;
      _updateCustomSourceTrigger(activeFilters.source);
    }`;

if (searchContent.includes(syncNeedle)) {
  searchContent = searchContent.replace(syncNeedle, syncReplacement);
} else {
  console.error('syncNeedle not found');
  process.exit(1);
}

const customSelectHelpers = `
  function _updateCustomSourceTrigger(sourceVal) {
    const valueEl = document.getElementById('searchFilterSourceValue');
    const listbox = document.getElementById('searchFilterSourceListbox');
    const sourceLabels = {
      all: 'All sources',
      openlibrary: 'Open Library',
      google: 'Google Books',
    };
    if (valueEl) valueEl.textContent = sourceLabels[sourceVal] || 'All sources';
    if (listbox) {
      listbox.querySelectorAll('.custom-select-option').forEach(o => {
        const matches = (o.getAttribute('data-value') || 'all') === sourceVal;
        o.classList.toggle('is-selected', matches);
        o.setAttribute('aria-selected', matches ? 'true' : 'false');
      });
    }
  }

  function wireCustomSourceSelect() {
    const trigger = document.getElementById('searchFilterSourceTrigger');
    const listbox = document.getElementById('searchFilterSourceListbox');
    const input = document.getElementById('searchFilterSource');
    const valueEl = document.getElementById('searchFilterSourceValue');
    if (!trigger || !listbox || !input) return;

    const sourceLabels = {
      all: 'All sources',
      openlibrary: 'Open Library',
      google: 'Google Books',
    };

    const closeListbox = () => {
      listbox.hidden = true;
      trigger.setAttribute('aria-expanded', 'false');
    };

    const openListbox = () => {
      listbox.hidden = false;
      trigger.setAttribute('aria-expanded', 'true');
      const selected = listbox.querySelector('.is-selected') || listbox.firstElementChild;
      selected?.focus?.();
    };

    trigger.addEventListener('click', () => {
      if (listbox.hidden) openListbox();
      else closeListbox();
    });

    listbox.querySelectorAll('.custom-select-option').forEach(option => {
      option.addEventListener('click', () => {
        const val = option.getAttribute('data-value') || 'all';
        input.value = val;
        if (valueEl) valueEl.textContent = sourceLabels[val] || option.textContent;
        listbox.querySelectorAll('.custom-select-option').forEach(o => {
          const isSelected = o === option;
          o.classList.toggle('is-selected', isSelected);
          o.setAttribute('aria-selected', isSelected ? 'true' : 'false');
        });
        closeListbox();
        trigger.focus();
        input.dispatchEvent(new Event('input'));
        input.dispatchEvent(new Event('change'));
      });
    });

    document.addEventListener('click', (e) => {
      if (!trigger.contains(e.target) && !listbox.contains(e.target)) {
        closeListbox();
      }
    });

    trigger.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowDown' || e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        openListbox();
      }
    });

    listbox.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        closeListbox();
        trigger.focus();
      }
    });
  }
`;

const initNeedle = '    updateShortcutLabel();';
searchContent = searchContent.replace(initNeedle, `${initNeedle}\n    wireCustomSourceSelect();`);

// Prepend helpers before init
const initFnNeedle = '  function init() {';
searchContent = searchContent.replace(initFnNeedle, `${customSelectHelpers}\n${initFnNeedle}`);

fs.writeFileSync(searchPath, searchContent, 'utf8');
console.log('search.js updated successfully');

// Now append CSS to frontend/css/features/book-dialogs.css
const cssPath = 'frontend/css/features/book-dialogs.css';
const cssAppend = `
/* Custom Listbox Control for Search Source Filter */
.custom-select-wrapper {
  position: relative;
  width: 100%;
}
.custom-select-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 40px;
  padding: 8px 12px;
  background: var(--glass-fill-1);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  color: var(--text-body);
  font: inherit;
  cursor: pointer;
  text-align: left;
}
.custom-select-trigger:hover {
  background: var(--glass-fill-2);
}
.custom-select-trigger:focus-visible {
  outline: 2px solid var(--indigo);
  outline-offset: 2px;
}
.custom-select-listbox {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 50;
  margin: 0;
  padding: 4px;
  list-style: none;
  background: var(--glass-solid-1);
  border: 1px solid var(--glass-border);
