import { chromium } from 'playwright';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  const consoleMessages = [];
  const pageErrors = [];
  const failedRequests = [];

  page.on('console', msg => {
    consoleMessages.push({ type: msg.type(), text: msg.text() });
  });

  page.on('pageerror', err => {
    pageErrors.push(err.toString() + '\n' + (err.stack || ''));
  });

  page.on('requestfailed', req => {
    failedRequests.push({ url: req.url(), failure: req.failure() });
  });

  console.log('Navigating to https://libriq.app...');
  try {
    await page.goto('https://libriq.app', { waitUntil: 'networkidle', timeout: 30000 });
  } catch (e) {
    console.log('Navigation timeout or error:', e.message);
  }

  await page.waitForTimeout(3000);

  console.log('\n--- PAGE ERRORS ---');
  console.log(pageErrors.length ? pageErrors.join('\n---\n') : 'None');

  console.log('\n--- FAILED REQUESTS ---');
  console.log(failedRequests.length ? JSON.stringify(failedRequests, null, 2) : 'None');

  console.log('\n--- CONSOLE MESSAGES (warn/error) ---');
  const importantLogs = consoleMessages.filter(m => m.type === 'error' || m.type === 'warning' || m.text.includes('Firebase') || m.text.includes('LibriQ'));
  console.log(importantLogs.map(m => `[${m.type}] ${m.text}`).join('\n'));

  // Also check firebase state on window
  const fbState = await page.evaluate(() => {
    return {
      hasLibriqFirebase: typeof window.LibriqFirebase !== 'undefined',
      state: window.LibriqFirebase?.getState?.(),
      sessionContext: window.LibriqFirebase?.getSessionContext?.(),
      config: window.LibriqConfig
    };
  });
  console.log('\n--- EVALUATION STATE ---');
  console.log(JSON.stringify(fbState, null, 2));

  await browser.close();
})();

